// ShortedStocksServiceHandler is an implementation of the shorts.v1alpha1.ShortedStocksService
// service.
type ShortedStocksServiceHandler interface {
	// Shows top 10 short positions on the ASX over different periods of time.
	GetTopShorts(context.Context, *connect.Request[v1alpha1.GetTopShortsRequest]) (*connect.Response[v1alpha1.GetTopShortsResponse], error)
	// Get Industry TreeMap for short positions.
	GetIndustryTreeMap(context.Context, *connect.Request[v1alpha1.GetIndustryTreeMapRequest]) (*connect.Response[v1alpha11.IndustryTreeMap], error)
	// Provides an overview of a specific stock based on PRODUCT_CODE.
	GetStock(context.Context, *connect.Request[v1alpha1.GetStockRequest]) (*connect.Response[v1alpha11.Stock], error)
	// Provides a more in-depth breakdown of a particular stock's metadata.
	GetStockDetails(context.Context, *connect.Request[v1alpha1.GetStockDetailsRequest]) (*connect.Response[v1alpha11.StockDetails], error)
	// fetch time series data for a specific stock
	GetStockData(context.Context, *connect.Request[v1alpha1.GetStockDataRequest]) (*connect.Response[v1alpha11.TimeSeriesData], error)
	// Get all short positions for a specific trading date
	GetMarketByDate(context.Context, *connect.Request[v1alpha1.GetMarketByDateRequest]) (*connect.Response[v1alpha1.GetMarketByDateResponse], error)
	// Get available trading dates for market snapshots
	GetAvailableDates(context.Context, *connect.Request[v1alpha1.GetAvailableDatesRequest]) (*connect.Response[v1alpha1.GetAvailableDatesResponse], error)
	// Search stocks by symbol or company name
	SearchStocks(context.Context, *connect.Request[v1alpha1.SearchStocksRequest]) (*connect.Response[v1alpha1.SearchStocksResponse], error)
	// Get sync status for admin dashboard
	GetSyncStatus(context.Context, *connect.Request[v1alpha1.GetSyncStatusRequest]) (*connect.Response[v1alpha1.GetSyncStatusResponse], error)
	// Mint an API token for the user. Requires valid authentication.
	MintToken(context.Context, *connect.Request[v1alpha1.MintTokenRequest]) (*connect.Response[v1alpha1.MintTokenResponse], error)
	// Trigger key metrics sync for specific stocks. Admin only.
	SyncKeyMetrics(context.Context, *connect.Request[v1alpha1.SyncKeyMetricsRequest]) (*connect.Response[v1alpha1.SyncKeyMetricsResponse], error)
	// Trigger enrichment for a specific stock. Admin only.
	// Returns enrichment data for review before applying to company-metadata.
	EnrichStock(context.Context, *connect.Request[v1alpha1.EnrichStockRequest]) (*connect.Response[v1alpha1.EnrichStockResponse], error)
	// Get top stocks for enrichment batching/prioritization. Admin only.
	GetTopStocksForEnrichment(context.Context, *connect.Request[v1alpha1.GetTopStocksForEnrichmentRequest]) (*connect.Response[v1alpha1.GetTopStocksForEnrichmentResponse], error)
	// List pending enrichments awaiting review. Admin only.
	ListPendingEnrichments(context.Context, *connect.Request[v1alpha1.ListPendingEnrichmentsRequest]) (*connect.Response[v1alpha1.ListPendingEnrichmentsResponse], error)
	// Get a specific pending enrichment by ID. Admin only.
	GetPendingEnrichment(context.Context, *connect.Request[v1alpha1.GetPendingEnrichmentRequest]) (*connect.Response[v1alpha1.GetPendingEnrichmentResponse], error)
	// Approve or reject a pending enrichment. Admin only.
	ReviewEnrichment(context.Context, *connect.Request[v1alpha1.ReviewEnrichmentRequest]) (*connect.Response[v1alpha1.ReviewEnrichmentResponse], error)
	// Get enrichment job status by job ID. Admin only.
	GetEnrichmentJobStatus(context.Context, *connect.Request[v1alpha1.GetEnrichmentJobStatusRequest]) (*connect.Response[v1alpha1.GetEnrichmentJobStatusResponse], error)
	// List enrichment jobs with optional status filter. Admin only.
	ListEnrichmentJobs(context.Context, *connect.Request[v1alpha1.ListEnrichmentJobsRequest]) (*connect.Response[v1alpha1.ListEnrichmentJobsResponse], error)
	// Internal API for Stripe webhook: handle checkout completion (server-to-server only)
	HandleStripeCheckoutCompleted(context.Context, *connect.Request[v1alpha1.HandleStripeCheckoutCompletedRequest]) (*connect.Response[v1alpha1.HandleStripeCheckoutCompletedResponse], error)
	// Internal API for Stripe webhook: handle subscription updates (server-to-server only)
	HandleStripeSubscriptionUpdated(context.Context, *connect.Request[v1alpha1.HandleStripeSubscriptionUpdatedRequest]) (*connect.Response[v1alpha1.HandleStripeSubscriptionUpdatedResponse], error)
	// Get the current user's subscription status. Requires authentication.
	GetMySubscription(context.Context, *connect.Request[v1alpha1.GetMySubscriptionRequest]) (*connect.Response[v1alpha1.GetMySubscriptionResponse], error)
	// Get a weekly short report with narrative analysis
	GetWeeklyReport(context.Context, *connect.Request[v1alpha1.GetWeeklyReportRequest]) (*connect.Response[v1alpha1.GetWeeklyReportResponse], error)
	// Get extracted financial highlights for specific stocks
	GetStockFinancialHighlights(context.Context, *connect.Request[v1alpha1.GetStockFinancialHighlightsRequest]) (*connect.Response[v1alpha1.GetStockFinancialHighlightsResponse], error)
	// Get recent news articles for a specific stock
	GetStockNews(context.Context, *connect.Request[v1alpha1.GetStockNewsRequest]) (*connect.Response[v1alpha1.GetStockNewsResponse], error)
	// Get news semantically related to a stock (or to a specific article)
	GetRelatedNews(context.Context, *connect.Request[v1alpha1.GetRelatedNewsRequest]) (*connect.Response[v1alpha1.GetRelatedNewsResponse], error)
	// Get market-wide news across all stocks
	GetMarketNews(context.Context, *connect.Request[v1alpha1.GetMarketNewsRequest]) (*connect.Response[v1alpha1.GetMarketNewsResponse], error)
	// Get a single published editorial take by slug.
	GetEditorialTake(context.Context, *connect.Request[v1alpha1.GetEditorialTakeRequest]) (*connect.Response[v1alpha1.GetEditorialTakeResponse], error)
	// List recent published editorial takes (paginated).
	ListEditorialTakes(context.Context, *connect.Request[v1alpha1.ListEditorialTakesRequest]) (*connect.Response[v1alpha1.ListEditorialTakesResponse], error)
	// Admin: list all takes including drafts (admin-gated).
	ListEditorialTakesAdmin(context.Context, *connect.Request[v1alpha1.ListEditorialTakesAdminRequest]) (*connect.Response[v1alpha1.ListEditorialTakesAdminResponse], error)
	// Admin: publish a draft take (sets published_at = NOW()).
	PublishEditorialTake(context.Context, *connect.Request[v1alpha1.PublishEditorialTakeRequest]) (*connect.Response[v1alpha1.PublishEditorialTakeResponse], error)
	// Admin: partial update of a take's editable fields.
	UpdateEditorialTake(context.Context, *connect.Request[v1alpha1.UpdateEditorialTakeRequest]) (*connect.Response[v1alpha1.UpdateEditorialTakeResponse], error)
	// Admin: hard delete a take.
	DeleteEditorialTake(context.Context, *connect.Request[v1alpha1.DeleteEditorialTakeRequest]) (*connect.Response[v1alpha1.DeleteEditorialTakeResponse], error)
	// Admin: mark a take as tweet-published (called by the bot worker).
	MarkTakeTweetPublished(context.Context, *connect.Request[v1alpha1.MarkTakeTweetPublishedRequest]) (*connect.Response[v1alpha1.MarkTakeTweetPublishedResponse], error)
	// Admin: list takes in the tweet publish queue (published_at IS NOT NULL,
	// tweet_published_at IS NULL). Used by the bot worker.
	ListTweetPublishQueue(context.Context, *connect.Request[v1alpha1.ListTweetPublishQueueRequest]) (*connect.Response[v1alpha1.ListTweetPublishQueueResponse], error)
	// Get director (insider) trades for a specific stock
	GetDirectorTrades(context.Context, *connect.Request[v1alpha1.GetDirectorTradesRequest]) (*connect.Response[v1alpha1.GetDirectorTradesResponse], error)
	// Get dividend history for a specific stock
	GetDividendHistory(context.Context, *connect.Request[v1alpha1.GetDividendHistoryRequest]) (*connect.Response[v1alpha1.GetDividendHistoryResponse], error)
	// Get peer comparison for a stock within its industry
	GetPeerComparison(context.Context, *connect.Request[v1alpha1.GetPeerComparisonRequest]) (*connect.Response[v1alpha1.GetPeerComparisonResponse], error)
	// Screen stocks using compound filters across shorts, price, fundamentals, director trades, and news
	ScreenStocks(context.Context, *connect.Request[v1alpha1.ScreenStocksRequest]) (*connect.Response[v1alpha1.ScreenStocksResponse], error)
	// Get squeeze-radar and battleground (price up + shorts building) ranked stocks
	GetBattlegroundStocks(context.Context, *connect.Request[v1alpha1.GetBattlegroundStocksRequest]) (*connect.Response[v1alpha1.GetBattlegroundStocksResponse], error)
	// Get a stock's people (with their other companies) and narrative-similar companies
	GetStockGraph(context.Context, *connect.Request[v1alpha1.GetStockGraphRequest]) (*connect.Response[v1alpha1.GetStockGraphResponse], error)
	// Get a chronological feed of events for a stock (announcements, director trades, news, short spikes)
	GetEventTimeline(context.Context, *connect.Request[v1alpha1.GetEventTimelineRequest]) (*connect.Response[v1alpha1.GetEventTimelineResponse], error)
	// Get a stock's reputation/risk signals (adverse: court/sanctions/complaints; positive: awards/press)
	GetStockSignals(context.Context, *connect.Request[v1alpha1.GetStockSignalsRequest]) (*connect.Response[v1alpha1.GetStockSignalsResponse], error)
	// Latest house-price headline metrics by region (national/state/capital city).
	GetHousingOverview(context.Context, *connect.Request[v1alpha1.GetHousingOverviewRequest]) (*connect.Response[v1alpha1.GetHousingOverviewResponse], error)
	// A single house-price time series for a region and measure.
	GetHousePriceSeries(context.Context, *connect.Request[v1alpha1.GetHousePriceSeriesRequest]) (*connect.Response[v1alpha1.GetHousePriceSeriesResponse], error)
	// List all suburbs in a state with latest median price + key demographics.
	ListStateSuburbs(context.Context, *connect.Request[v1alpha1.ListStateSuburbsRequest]) (*connect.Response[v1alpha1.ListStateSuburbsResponse], error)
	// Full per-suburb profile: identity, demographics, headline price, comparison baselines.
	GetSuburbProfile(context.Context, *connect.Request[v1alpha1.GetSuburbProfileRequest]) (*connect.Response[v1alpha1.GetSuburbProfileResponse], error)
	// List house-price regions (suburbs/LGAs/etc) for the suburb explorer.
	ListHousingRegions(context.Context, *connect.Request[v1alpha1.ListHousingRegionsRequest]) (*connect.Response[v1alpha1.ListHousingRegionsResponse], error)
}

